struct Writer {FILE* f;explicit Writer(const std::string& p):f(std::fopen(p.c_str(),"wx")){if(!f)throw std::runtime_error("exclusive native voice wire");}void word(u32 x){u8 b[4];store_be32(b,x);if(std::fwrite(b,1,4,f)!=4)throw std::runtime_error("native voice word");}void sample(s16 x){u8 b[2];store_be16(b,std::bit_cast<u16>(x));if(std::fwrite(b,1,2,f)!=2)throw std::runtime_error("native voice PCM");}void close(){if(std::fclose(f))throw std::runtime_error("native voice close");}};
void snapshot(Writer& out,const StoryGuideVoicePcmSnapshot& s){for(u32 x:{u32(s.phase),u32(s.generation),s.key,u32(s.paused),u32(s.pause72),u32(s.sdk_volume),s.decoder.position,s.decoder.phase,u32(s.decoder.rendered),u32(s.decoder.playing),s.conversion.phase,u32(s.conversion.inputs),u32(s.conversion.outputs),s.buffered_position,u32(s.output_remaining),u32(s.voice_frames),u32(s.bus_frames),u32(s.control_frames),u32(s.failed),u32(s.pending),u32(s.native_status())})out.word(x);}
